<script lang="ts">
  /**
   * Comparativo 2022 × 2026 — "<Casa> | 2022 × 2026".
   *
   * Pedido do Douglas em 23/09/2026, a partir da imagem "AtlasIntel | 2022 X
   * 2026": a comparação das pesquisas perto da eleição com as de 2022, com o
   * valor escrito em todo ponto, as fotos dos candidatos e leituras
   * automáticas embaixo. Identidade visual clara do Radar (não o tema escuro
   * da imagem).
   *
   * Regras que esta página não pode quebrar (contrato cycle_comparison.json):
   *  - valor como a casa publicou (votos totais), sem renormalizar nem
   *    corrigir; uma casa por gráfico; 1º e 2º turno nunca se misturam;
   *  - 2022 "2º turno" = simulações Lula × Jair divulgadas ANTES do 1º turno;
   *  - a página só exibe: margem, empate técnico e leituras vêm do Python;
   *  - a camada "imprensa conferida" é descritiva e aparece rotulada; ela
   *    nunca entra no agregado, no consenso ou nos pesos (isso é do backend,
   *    aqui só se mostra o selo e a legenda).
   */
  import CandidatePortrait from '../components/CandidatePortrait.svelte';
  import DataTable from '../components/DataTable.svelte';
  import InsightsPanel from '../components/InsightsPanel.svelte';
  import LabelledLineChart from '../components/LabelledLineChart.svelte';
  import {
    changeText,
    CYCLE_ROUTE,
    daysLabel,
    distanceFromKey,
    formatDayMonth,
    lastChange,
    markerPlacement,
    orderedPanels,
    paddedDomain,
    panelSeries,
    panelTiers,
    roundChanges,
    sameDistanceLine,
    sameDistanceSeries,
    sharedYDomain,
    sortedRounds,
    TIER_ORDER,
    tierLegendText,
    tierShortLabel,
  } from '../lib/cycleComparison';
  import { formatDate, formatNumber, formatPublishedNumber, formatSigned } from '../lib/format';
  import type { CycleComparisonPayload, CycleKpiRound, CyclePanel, CycleTurn } from '../lib/types';

  export let comparison: CycleComparisonPayload;
  export let initialHouse = '';
  /** Muda a cada navegação do App: relê o ?casa= mesmo quando o texto é igual ao anterior. */
  export let navKey = 0;

  const TURNS: CycleTurn[] = [1, 2];

  let houseId = '';
  let syncedKey = -1;
  $: if (navKey !== syncedKey) {
    syncedKey = navKey;
    houseId = initialHouse;
  }

  $: houses = comparison.houses;
  $: fallbackHouse = houses.some((item) => item.house_id === comparison.default_house_id)
    ? (comparison.default_house_id ?? '')
    : (houses[0]?.house_id ?? '');
  // ?casa= desconhecida ou vazia → casa padrão do contrato (a página nunca fica sem casa).
  $: if (!houses.some((item) => item.house_id === houseId)) houseId = fallbackHouse;
  $: house = houses.find((item) => item.house_id === houseId) ?? null;

  /** A escolha fica no endereço (?casa=), sem criar entrada nova no histórico do navegador. */
  function selectHouse(id: string): void {
    houseId = id;
    const url = new URL(window.location.href);
    url.searchParams.set('casa', id);
    const next = `${url.pathname}${url.search}${url.hash}`;
    if (next !== `${window.location.pathname}${window.location.search}${window.location.hash}`) {
      window.history.replaceState({}, '', next);
    }
  }

  $: lulaLabel = comparison.candidates.lula?.label ?? 'Lula';
  $: lulaId = comparison.candidates.lula?.candidate_id ?? '';
  $: jairLabel = comparison.candidates.jair_2022?.label ?? 'Jair Bolsonaro';
  $: flavioLabel = comparison.candidates.flavio_2026?.label ?? 'Flávio Bolsonaro';
  $: electionT1 = (year: number) => comparison.elections.find((item) => item.year === year && item.turn === 1)?.date ?? '';

  $: panels = house ? orderedPanels(house) : [];
  // Domínio Y comum POR TURNO entre 2022 e 2026 (exceção pedida pelo Douglas em 23/09/2026).
  $: domains = { 1: sharedYDomain(panels, 1), 2: sharedYDomain(panels, 2) } as Record<CycleTurn, [number, number] | null>;
  $: charts = panels.map((panel) => {
    const rival = comparison.candidates[panel.rival_key];
    const markers = (house?.markers ?? []).filter((marker) => marker.year === panel.year && marker.turns.includes(panel.turn));
    const tiers = panelTiers(panel, comparison.provenance_tiers);
    return {
      panel,
      key: `${panel.year}-${panel.turn}`,
      series: panelSeries(panel, comparison.candidates),
      rounds: sortedRounds(panel),
      markers: markers.map((marker) => ({
        ...marker,
        placement: markerPlacement(panel.rounds.map((round) => round.published_at), marker.date, 0.5),
      })),
      chartMarkers: markers.map((marker) => ({ date: marker.date, label: marker.label, detail: marker.detail })),
      // "Imprensa conferida" ganha selo próprio no topo do painel; a linha de proveniência lista o resto.
      tiers: tiers.filter((item) => item.tier !== 'press_verified'),
      pressVerified: tiers.some((item) => item.tier === 'press_verified'),
      rivalId: rival?.candidate_id ?? '',
      rivalLabel: rival?.label ?? 'Adversário',
      domain: domains[panel.turn],
      changes: roundChanges(panel),
    };
  });

  $: kpiCards = TURNS.map((turn) => {
    const kpi = house?.kpis.find((item) => item.turn === turn) ?? null;
    const panelFor = (year: number) => panels.find((panel) => panel.year === year && panel.turn === turn);
    return {
      turn,
      kpi,
      sameDistance: kpi ? sameDistanceLine(kpi.same_distance_2022, formatSigned) : null,
      change2022: lastChange(panelFor(2022)),
      change2026: lastChange(panelFor(2026)),
    };
  });

  $: distanceCharts = TURNS.map((turn) => {
    const series = house ? sameDistanceSeries(house, turn, comparison.candidates) : [];
    const values = series.flatMap((item) => item.points.map((point) => point.value));
    return {
      turn,
      series,
      legend: series.map((item) => {
        const year = Number(item.key.replace('margem-', ''));
        const rival = year === 2022 ? comparison.candidates.jair_2022 : comparison.candidates.flavio_2026;
        return { key: item.key, year, color: item.color ?? '#555', dashed: Boolean(item.dashed), rivalId: rival?.candidate_id ?? '', rivalLabel: rival?.label ?? 'Adversário' };
      }),
      // O zero (empate) entra sempre no domínio: a linha de referência precisa aparecer.
      domain: paddedDomain([0, ...values], { step: 5, floor: -100, ceiling: 100 }),
    };
  });

  // Legenda do selo sem repetir o nome do selo ("Imprensa conferida: …").
  $: pressLegend = (comparison.provenance_tiers.press_verified ?? '').replace(/^imprensa conferida\s*[:—-]\s*/i, '');
  $: readings = panels.map((panel) => ({ key: `${panel.year}-${panel.turn}`, panel, reading: panel.reading }));
  $: insightsBlock = house ? { insights: house.insights, generation: comparison.generation } : null;
  // Legenda do rodapé em ordem fixa e sem repetir o rótulo em negrito.
  $: tierLegend = TIER_ORDER.filter((tier) => comparison.provenance_tiers[tier]).map((tier) => ({
    tier,
    text: tierLegendText(tier, comparison.provenance_tiers[tier]),
  }));

  function kindText(panel: CyclePanel): string {
    if (panel.scenario_kind === 'runoff_simulation_pre_t1') {
      const t1 = electionT1(panel.year);
      return `2º turno simulado (${lulaLabel} × ${jairLabel}), divulgado antes do 1º turno${t1 ? ` de ${formatDate(t1)}` : ''} — não é o 2º turno real`;
    }
    if (panel.scenario_kind === 'runoff_simulation') return `Simulação de 2º turno ${lulaLabel} × ${flavioLabel}`;
    return `1º turno · cenário como a casa publicou`;
  }

  function panelTitle(panel: CyclePanel): string {
    return `${house?.house_name ?? ''} ${panel.year}, ${panel.turn}º turno`;
  }

  function kpiRoundText(round: CycleKpiRound, rival: string): string {
    return `${lulaLabel} ${formatNumber(round.lula_pct)} × ${rival} ${formatNumber(round.rival_pct)} · divulgação ${formatDate(round.published_at)}, a ${daysLabel(round.days_to_first_round)} do 1º turno`;
  }

  function moeText(value: number | null | undefined): string {
    return value == null ? 'não declarada' : `±${formatPublishedNumber(value)} p.p.`;
  }

  const distanceX = (key: string): string => String(distanceFromKey(key));
  const distanceXLong = (key: string): string => `${daysLabel(distanceFromKey(key))} antes do 1º turno`;
  const signedValue = (value: number): string => formatSigned(value);
  const change = (value: number): string => changeText(value, formatNumber);
  const changeWord = (value: number): string => (Math.abs(value) < 0.05 ? 'igual' : value > 0 ? 'subiu' : 'caiu');
</script>

<section class="page-stack cycle-page" aria-labelledby="cycle-title" data-testid="cycle-comparison">
  <header class="live-page-hero cycle-hero">
    <div>
      <p class="mini-label">Comparativo · uma casa, duas eleições</p>
      <h1 id="cycle-title">{house?.house_name ?? 'Comparativo'} <span>| 2022 × 2026</span></h1>
      <p class="cycle-subtitle">Histórico presidencial de 1º e 2º turnos · votos totais</p>
      <p class="cycle-pairs">2022: {lulaLabel} × {jairLabel} · 2026: {lulaLabel} × {flavioLabel}</p>
      {#if house?.lineage_note}<p class="cycle-lineage">{house.lineage_note}</p>{/if}
    </div>
    {#if houses.length > 1}
      <label class="cycle-house-select">
        <span>Casa</span>
        <select value={houseId} onchange={(event) => selectHouse((event.currentTarget as HTMLSelectElement).value)}>
          {#each houses as item (item.house_id)}
            <option value={item.house_id}>{item.house_name}</option>
          {/each}
        </select>
      </label>
    {/if}
  </header>

  {#if house}
    <div class="cycle-kpis" role="group" aria-label="Margem da última rodada exibida, por turno">
      {#each kpiCards as card (card.turn)}
        <article class="cycle-kpi" data-turn={card.turn} aria-labelledby={`cycle-kpi-title-${card.turn}`}>
          <header>
            <h2 id={`cycle-kpi-title-${card.turn}`} class="mini-label">{card.turn}º turno · última rodada exibida</h2>
            <p class="cycle-kpi-sub">Diferença: {lulaLabel} menos adversário</p>
          </header>
          <dl class="cycle-kpi-values">
            <div data-year="2022">
              <dt>2022</dt>
              <dd>
                {#if card.kpi?.latest_2022}
                  <strong class="cycle-kpi-margin" data-margin={card.kpi.latest_2022.margin_pp}>{formatSigned(card.kpi.latest_2022.margin_pp)} p.p.</strong>
                  <small>{kpiRoundText(card.kpi.latest_2022, jairLabel)}</small>
                  {#if card.change2022}
                    <small class="cycle-kpi-change" data-testid="kpi-change-2022">
                      Frente à rodada de {formatDayMonth(card.change2022.previous.published_at)}:
                      {lulaLabel} <b class="cycle-change" data-direction={changeWord(card.change2022.lula)}>{change(card.change2022.lula)}</b> ·
                      {jairLabel} <b class="cycle-change" data-direction={changeWord(card.change2022.rival)}>{change(card.change2022.rival)}</b>
                    </small>
                  {/if}
                {:else}
                  <strong class="cycle-kpi-margin cycle-kpi-empty">—</strong><small>sem rodada desta casa</small>
                {/if}
              </dd>
            </div>
            <div data-year="2026">
              <dt>2026</dt>
              <dd>
                {#if card.kpi?.latest_2026}
                  <strong class="cycle-kpi-margin" data-margin={card.kpi.latest_2026.margin_pp}>{formatSigned(card.kpi.latest_2026.margin_pp)} p.p.</strong>
                  <small>{kpiRoundText(card.kpi.latest_2026, flavioLabel)}</small>
                  {#if card.change2026}
                    <small class="cycle-kpi-change" data-testid="kpi-change-2026">
                      Frente à rodada de {formatDayMonth(card.change2026.previous.published_at)}:
                      {lulaLabel} <b class="cycle-change" data-direction={changeWord(card.change2026.lula)}>{change(card.change2026.lula)}</b> ·
                      {flavioLabel} <b class="cycle-change" data-direction={changeWord(card.change2026.rival)}>{change(card.change2026.rival)}</b>
                    </small>
                  {/if}
                {:else}
                  <strong class="cycle-kpi-margin cycle-kpi-empty">—</strong><small>sem rodada desta casa</small>
                {/if}
              </dd>
            </div>
          </dl>
          {#if card.kpi?.technical_tie_2026}
            <p class="cycle-tie" data-testid="technical-tie">
              <span class="cycle-tie-badge">Empate técnico em 2026</span>
              <span>margem de erro {moeText(card.kpi.latest_2026?.margin_of_error)} · {comparison.tie_rule.text}</span>
            </p>
          {/if}
          {#if card.sameDistance}
            <p class="cycle-same-distance" data-testid="same-distance">Mesma distância: {card.sameDistance}</p>
          {/if}
        </article>
      {/each}
    </div>

    <div class="cycle-grid">
      {#each charts as chart (chart.key)}
        <article class="live-chart-card cycle-panel" data-panel={chart.key} data-status={chart.panel.status} aria-labelledby={`cycle-panel-title-${chart.key}`}>
          <header class="cycle-panel-head">
            <div>
              <p class="mini-label">{chart.panel.year}</p>
              <h2 id={`cycle-panel-title-${chart.key}`}>{chart.panel.turn}º turno</h2>
              <p class="cycle-panel-kind">{kindText(chart.panel)}</p>
            </div>
            <div class="cycle-portraits" aria-label={`${lulaLabel} × ${chart.rivalLabel}`} role="group">
              <span class="cycle-portrait" style="--ring:#c1652c"><CandidatePortrait candidateId={lulaId} label={lulaLabel} size="small" /></span>
              <span class="cycle-versus" aria-hidden="true">×</span>
              <span class="cycle-portrait" style="--ring:#2a78d6"><CandidatePortrait candidateId={chart.rivalId} label={chart.rivalLabel} size="small" /></span>
            </div>
          </header>

          {#if chart.panel.status === 'available' && chart.rounds.length}
            {#if chart.pressVerified}
              <p class="cycle-press-badge" data-testid="press-verified">
                <span>Imprensa conferida</span>
                {pressLegend}
              </p>
            {/if}
            <LabelledLineChart
              series={chart.series}
              decimals={1}
              unit="%"
              yDomain={chart.domain}
              yStep={5}
              formatX={formatDayMonth}
              formatXLong={formatDate}
              xAxisLabel="divulgação"
              markers={chart.chartMarkers}
              markerOffsetDays={0.5}
              responsive
              minBand={38}
              showTable={false}
              showDeltas
              deltaNote="variação frente à rodada anterior desta casa, em pontos"
              tableLabel={`Valores de ${panelTitle(chart.panel)}`}
              ariaLabel={`${panelTitle(chart.panel)}: ${lulaLabel} e ${chart.rivalLabel} em cada rodada, votos totais`}
            />
            <p class="cycle-note">
              Base: votos totais, como a casa publicou (sem renormalizar nem corrigir). Eixo X: data de
              divulgação. Escala vertical igual à do {chart.panel.turn}º turno de {chart.panel.year === 2022 ? 2026 : 2022}.
              {chart.rounds.length} {chart.rounds.length === 1 ? 'rodada' : 'rodadas'}.
              {#if chart.rounds.length === 1}Rodada única: a série começa a existir na próxima pesquisa desta casa.{/if}
            </p>
            {#if chart.markers.length}
              <ul class="cycle-events" aria-label="Eventos marcados no gráfico">
                {#each chart.markers as marker (marker.id)}
                  <li>
                    <strong>{marker.label}</strong> ({formatDate(marker.date)}): {marker.detail}
                    {#if marker.placement === 'after'}<em>Fica depois da última rodada exibida: não aparece no gráfico.</em>{/if}
                    {#if marker.placement === 'before'}<em>Fica antes da primeira rodada exibida: não aparece no gráfico.</em>{/if}
                    {#each marker.sources as source}
                      <a href={source.url} target="_blank" rel="noreferrer">{source.label} ↗</a>
                    {/each}
                  </li>
                {/each}
              </ul>
              <p class="cycle-note cycle-note-muted">
                {#if chart.markers.some((marker) => marker.placement === 'inside')}Linha tracejada = evento de contexto.{/if}
                Um evento no mesmo dia de uma divulgação é posto logo depois dela: nenhuma pesquisa divulgada
                naquele dia teve campo depois do evento. Marcar um evento não afirma que ele moveu a pesquisa.
              </p>
            {/if}
            {#if chart.tiers.length}
              <p class="cycle-provenance">
                <span>Proveniência:</span>
                {#each chart.tiers as item (item.tier)}
                  <span class={`cycle-tier tier-${item.tier}`}>{item.text}</span>
                {/each}
              </p>
            {/if}
            <details class="cycle-table">
              <summary>Ver os valores e as fontes</summary>
              <DataTable label={`Valores de ${panelTitle(chart.panel)}`}>
                <table>
                  <thead>
                    <tr>
                      <th scope="col">Divulgação</th>
                      <th scope="col">Campo</th>
                      <th scope="col">Registro</th>
                      <th scope="col" class="num">{lulaLabel}</th>
                      <th scope="col" class="num">{chart.rivalLabel}</th>
                      <th scope="col" class="num">Diferença</th>
                      <th scope="col">Amostra · margem</th>
                      <th scope="col">Origem</th>
                    </tr>
                  </thead>
                  <tbody>
                    {#each chart.rounds as round (`${round.published_at}|${round.registration_no ?? ''}`)}
                      {@const roundChange = chart.changes.get(`${round.published_at}|${round.registration_no ?? ''}`)}
                      <tr>
                        <th scope="row">{formatDate(round.published_at)}</th>
                        <td>{round.field_start && round.field_end ? `${formatDayMonth(round.field_start)}–${formatDayMonth(round.field_end)}` : '—'}</td>
                        <td>{round.registration_no ?? '—'}</td>
                        <td class="num">{formatNumber(round.lula_pct)}%{#if roundChange} <span class="cycle-change" data-direction={changeWord(roundChange.lula)}>{change(roundChange.lula)}</span>{/if}</td>
                        <td class="num">{formatNumber(round.rival_pct)}%{#if roundChange} <span class="cycle-change" data-direction={changeWord(roundChange.rival)}>{change(roundChange.rival)}</span>{/if}</td>
                        <td class="num">{formatSigned(round.margin_pp)}</td>
                        <td>{round.sample_size ? new Intl.NumberFormat('pt-BR').format(round.sample_size) : '—'} · {moeText(round.margin_of_error)}{round.scenario_note ? ` · ${round.scenario_note}` : ''}</td>
                        <td>
                          {tierShortLabel(round.provenance.tier)}
                          {#each round.provenance.sources as source}
                            <a href={source.url} target="_blank" rel="noreferrer">{source.label} ↗</a>
                          {/each}
                        </td>
                      </tr>
                    {/each}
                  </tbody>
                </table>
              </DataTable>
            </details>
          {:else}
            <p class="recent-empty cycle-unavailable">{chart.panel.reason ?? 'Sem rodada desta casa neste turno.'}</p>
          {/if}
        </article>
      {/each}
    </div>

    <section class="live-chart-card cycle-reading" aria-labelledby="cycle-reading-title">
      <header class="section-title-row">
        <div>
          <p class="mini-label">Leitura da série</p>
          <h2 id="cycle-reading-title">Diferença {lulaLabel} − adversário, da primeira à última rodada</h2>
        </div>
      </header>
      <dl class="cycle-reading-grid">
        {#each readings as item (item.key)}
          <div data-panel={item.key}>
            <dt>{item.panel.year} · {item.panel.turn}º turno</dt>
            <dd>
              {#if item.reading}
                <span class="cycle-reading-values">{formatSigned(item.reading.first_margin_pp)} → <strong>{formatSigned(item.reading.last_margin_pp)} p.p.</strong></span>
                <small>{formatDate(item.reading.first_published_at)} → {formatDate(item.reading.last_published_at)} · variação {formatSigned(item.reading.change_pp)} p.p.</small>
                {#if item.reading.scenario_change}
                  <small class="cycle-reading-note">Atenção: {item.reading.scenario_change}.</small>
                {/if}
              {:else}
                <small>{item.panel.reason ?? 'Sem rodadas.'}</small>
              {/if}
            </dd>
          </div>
        {/each}
      </dl>
    </section>

    <section class="live-chart-card cycle-distance" aria-labelledby="cycle-distance-title">
      <header class="section-title-row">
        <div>
          <p class="mini-label">Mesma distância da eleição</p>
          <h2 id="cycle-distance-title">A diferença a igual número de dias do 1º turno</h2>
          <p>
            Diferença {lulaLabel} − adversário (em pontos percentuais) de cada rodada, posta pela distância em
            dias entre a divulgação e o 1º turno do seu ano. 2022 e 2026 no mesmo gráfico; acima de zero,
            {lulaLabel} à frente. Uma coluna por distância com rodada publicada (colunas equiespaçadas).
          </p>
        </div>
      </header>
      <div class="cycle-distance-grid">
        {#each distanceCharts as item (item.turn)}
          <div class="cycle-distance-chart" data-turn={item.turn}>
            {#if item.series.length}
              <header class="cycle-distance-head">
                <strong>{item.turn}º turno</strong>
                <span>{item.turn === 2 ? '2022: simulação divulgada antes do 1º turno · 2026: simulação Lula × Flávio' : 'cenário de 1º turno como a casa publicou'}</span>
              </header>
              <ul class="cycle-distance-legend" aria-label="Séries do gráfico">
                {#each item.legend as entry (entry.key)}
                  <li style={`--series-color:${entry.color}`} data-year={entry.year}>
                    <i aria-hidden="true" class:dashed={entry.dashed}></i>
                    <span class="cycle-distance-year">{entry.year}</span>
                    <span class="cycle-portrait cycle-portrait-mini" style="--ring:#c1652c"><CandidatePortrait candidateId={lulaId} label={lulaLabel} size="small" /></span>
                    <span class="cycle-versus" aria-hidden="true">×</span>
                    <span class="cycle-portrait cycle-portrait-mini" style="--ring:#2a78d6"><CandidatePortrait candidateId={entry.rivalId} label={entry.rivalLabel} size="small" /></span>
                    <span class="cycle-distance-pair">{lulaLabel} − {entry.rivalLabel.split(/\s+/)[0]}</span>
                  </li>
                {/each}
                <li class="cycle-distance-zero"><span>acima de 0: {lulaLabel} à frente · abaixo: adversário à frente</span></li>
              </ul>
              <LabelledLineChart
                series={item.series}
                showLegend={false}
                unit=""
                formatValue={signedValue}
                yDomain={item.domain}
                yStep={5}
                referenceValue={0}
                avoidLines
                formatX={distanceX}
                formatXLong={distanceXLong}
                xAxisLabel="dias até o 1º turno, pela data de divulgação"
                responsive
                minBand={40}
                tableLabel={`Diferença por distância da eleição, ${item.turn}º turno`}
                ariaLabel={`${house.house_name}, ${item.turn}º turno: diferença ${lulaLabel} menos adversário por dias até o 1º turno, 2022 e 2026`}
              />
            {:else}
              <p class="recent-empty">Sem rodadas desta casa no {item.turn}º turno.</p>
            {/if}
          </div>
        {/each}
      </div>
    </section>

    {#if insightsBlock && insightsBlock.insights.length}
      <InsightsPanel
        insights={insightsBlock}
        kicker={`Leitura automática · ${house.house_name}`}
        title="O que o comparativo mostra"
        headingId="cycle-insights-title"
        intro="Cada frase sai de uma regra determinística sobre as séries publicadas (votos totais). Nenhuma é escrita por modelo de linguagem e nenhuma afirma causa: um evento marcado no gráfico é contexto, não explicação."
      />
    {:else}
      <p class="inline-note">Sem leitura automática para {house.house_name} neste run.</p>
    {/if}

    <footer class="cycle-footnote">
      <p>
        <strong>Como ler.</strong> Cada gráfico mostra uma casa só, com o número que ela divulgou em votos totais
        (inclui indecisos, brancos e nulos). 2022 e 2026 do mesmo turno usam a mesma escala vertical, que não começa
        em zero, para as duas eleições ficarem comparáveis ponto a ponto. {comparison.tie_rule.text}
        {#if comparison.stability_rule?.text}{comparison.stability_rule.text}{/if}
      </p>
      <p>
        {#each tierLegend as item (item.tier)}
          <span class="cycle-tier-legend"><b>{tierShortLabel(item.tier)}:</b> {item.text}.</span>
        {/each}
      </p>
      {#if comparison.context_events.length}
        <details class="cycle-context">
          <summary>Eventos de contexto e fontes ({comparison.context_events.length})</summary>
          <ul>
            {#each comparison.context_events as event (event.id)}
              <li>
                <strong>{event.label}</strong> ({formatDate(event.date)}): {event.detail}
                {#each event.sources as source}
                  <a href={source.url} target="_blank" rel="noreferrer">{source.label} ↗</a>
                {/each}
              </li>
            {/each}
          </ul>
        </details>
      {/if}
      <p class="cycle-run">
        Run <code>{comparison.run_id}</code> · versão {comparison.version} · dados de {formatDate(comparison.as_of)} ·
        <a href="/data/latest/cycle_comparison.json">contrato em JSON</a> ·
        <a href={`${CYCLE_ROUTE}?casa=${encodeURIComponent(house.house_id)}`} data-route>link desta casa</a>
      </p>
    </footer>
  {:else}
    <section class="load-state"><p class="eyebrow">Comparativo 2022 × 2026</p><h2>Nenhuma casa com rodadas nos dois ciclos neste run.</h2></section>
  {/if}
</section>
