<script lang="ts">
  /**
   * Gráfico de linhas "estilo Quaest": até 3 séries, o número escrito em
   * TODOS os pontos, uma medição por coluna do eixo X.
   *
   * Pedido do Douglas em 02/09/2026 a partir do gráfico Genial/Quaest do 2º
   * turno (Lula 42 × Flávio 41): "acho de fácil entendimento e bom". A regra
   * geral de dataviz (rótulo seletivo) é relaxada de propósito aqui, e só
   * aqui: com ≤3 séries e ≤12 pontos cada, escrever todos os valores é o que
   * torna o gráfico legível sem tooltip — que existe mesmo assim.
   *
   * O componente é genérico: recebe séries já resolvidas (rótulo, cor,
   * pontos com data e valor) e não sabe de onde vieram. A paleta padrão
   * (#2a78d6, #c1652c, #7c5cc4) passou no validador do skill dataviz
   * (banda de luminosidade, croma, CVD, contraste).
   */
  import DataTable from './DataTable.svelte';
  import { markerX } from '../lib/cycleComparison';
  import { formatDate, formatNumber } from '../lib/format';

  import type { LabelledMarker, LabelledPoint, LabelledSeries } from '../lib/types';

  export let series: LabelledSeries[] = [];
  export let title = '';
  export let description = '';
  export let unit = '%';
  /** Casas decimais do rótulo de cada ponto (0 reproduz o inteiro publicado). */
  export let decimals = 0;
  export let tableLabel = 'Valores do gráfico';
  export let ariaLabel = 'Gráfico de linhas com rótulo em cada ponto';

  // Props acrescentadas para o comparativo 2022 × 2026 (23/09/2026). Todas
  // têm padrão que reproduz o desenho anterior no resto do site.
  /** Domínio Y [min, max]; null = eixo começa em zero (regra geral do skill). */
  export let yDomain: [number, number] | null = null;
  /** Passo dos ticks do eixo Y; null = 10 em 10 (20 em 20 acima de 60). */
  export let yStep: number | null = null;
  /** Rótulo curto do eixo X (padrão: dd/mm/aaaa). */
  export let formatX: (value: string) => string = formatDate;
  /** Rótulo longo do X no tooltip, na tabela e no texto acessível (padrão: o mesmo do eixo). */
  export let formatXLong: ((value: string) => string) | null = null;
  /** Formato do número escrito em cada ponto (padrão: `decimals`). */
  export let formatValue: ((value: number) => string) | null = null;
  /** Legenda embaixo do eixo X (ex.: "divulgação"). */
  export let xAxisLabel = '';
  /** Linhas verticais tracejadas de eventos; x interpolado entre as colunas vizinhas. */
  export let markers: LabelledMarker[] = [];
  /** Deslocamento do evento dentro do dia (0,5 = depois das divulgações do mesmo dia). */
  export let markerOffsetDays = 0;
  /** Linha horizontal de referência (ex.: 0 = empate na margem). */
  export let referenceValue: number | null = null;
  /** Largura medida no contêiner (texto em tamanho real no celular); false = viewBox fixo de 760. */
  export let responsive = false;
  /** Tabela de valores embutida (details); a página pode desenhar a sua. */
  export let showTable = true;
  /**
   * Colunas com UM ponto só (séries que não dividem as mesmas datas, ex.:
   * "mesma distância" 2022 × 2026): o rótulo vai para o lado, acima ou
   * abaixo, que não cruza nenhuma linha. false = regra antiga (sempre acima).
   */
  export let avoidLines = false;
  /**
   * Largura mínima de cada coluna (px), só no modo responsivo. Quando o
   * contêiner é estreito demais para o número de rodadas (celular, casa com
   * 8–10 rodadas e 1 decimal), o gráfico fica mais largo que a tela e rola
   * na horizontal dentro do próprio quadro: o número de todo ponto continua
   * no tamanho real e sem encostar no vizinho. 0 = desligado (padrão).
   */
  export let minBand = 0;
  /**
   * Variação frente à rodada anterior da MESMA série, escrita pequena junto do
   * número de cada ponto (▲ subiu, ▼ caiu, = igual). Pedido do Douglas em
   * 28/09/2026 para o comparativo: "quanto o candidato subiu ou caiu da última
   * pesquisa para a atual… no mesmo gráfico para não poluir".
   */
  export let showDeltas = false;
  /** Nota curta na legenda explicando os números pequenos (só com showDeltas). */
  export let deltaNote = 'variação frente à rodada anterior, em pontos';
  /** false = a página desenha a própria legenda (ex.: com as fotos). */
  export let showLegend = true;

  const PALETTE = ['#2a78d6', '#c1652c', '#7c5cc4'];
  const BASE_WIDTH = 760;
  // Espaço vertical mínimo entre dois centros para um rótulo caber entre eles (marca + texto + folga).
  const LABEL_GAP = 34;
  // Largura média de um caractere dos rótulos de 10,5 px (para ralear datas e empilhar eventos).
  const CHAR_WIDTH = 6;
  // Rótulo de evento (10,5 px, negrito): medido no Chromium, ~6,45 px por caractere.
  const EVENT_CHAR = 6.5;

  let hoveredIndex: number | null = null;
  let measuredWidth = 0;

  $: longX = formatXLong ?? formatX;
  $: shown = series.slice(0, 3).map((item, index) => ({ ...item, color: item.color ?? PALETTE[index] }));
  $: dates = [...new Set(shown.flatMap((item) => item.points.map((point) => point.date)))].sort();
  $: values = shown.flatMap((item) => item.points.map((point) => point.value));
  $: maxValue = values.length ? Math.max(...values) : 50;
  // Sem domínio explícito o eixo começa em zero: uma diferença de 1 ponto deve parecer 1 ponto.
  $: yMin = yDomain ? yDomain[0] : 0;
  $: yMax = yDomain ? Math.max(yDomain[1], yDomain[0] + 1) : Math.max(10, Math.ceil((maxValue + 6) / 10) * 10);
  $: tickStep = yStep && yStep > 0 ? yStep : yDomain ? Math.max(1, Math.ceil((yMax - yMin) / 6)) : yMax <= 60 ? 10 : 20;
  $: yTicks = Array.from(
    { length: Math.floor((yMax - yMin) / tickStep + 1e-9) + 1 },
    (_, index) => Math.round((yMin + index * tickStep) * 1e6) / 1e6,
  );

  // Toda a geometria é derivada aqui, em blocos reativos, e o template só
  // lê o resultado: em modo legado o Svelte não rastreia o que uma função
  // auxiliar lê por dentro, e o desenho ficava com coordenadas velhas ao
  // trocar de casa/turno.
  // 1) Horizontal: largura, colunas e marcadores (não dependem da altura).
  $: naturalWidth = responsive && measuredWidth > 0 ? Math.max(260, Math.round(measuredWidth)) : BASE_WIDTH;
  // left (48) + folga interna (2 × 20) + right (32) em volta das colunas.
  $: neededWidth = responsive && minBand > 0 && dates.length > 1 ? 48 + 40 + (dates.length - 1) * minBand + 32 : 0;
  $: width = Math.max(naturalWidth, Math.ceil(neededWidth));
  $: scrollable = responsive && measuredWidth > 0 && width > Math.round(measuredWidth) + 1;
  const left = 48;
  $: right = width - 32;
  $: xs = dates.map((_, index) => {
    if (dates.length <= 1) return (left + right) / 2;
    const inner = right - left - 40;
    return left + 20 + (index / (dates.length - 1)) * inner;
  });
  $: bandWidth = dates.length > 1 ? (right - left - 40) / (dates.length - 1) : right - left;
  // Rótulos do eixo X: no modo responsivo, um a cada `xEvery` colunas quando não cabem todos (o último sempre aparece).
  $: xLabelWidth = Math.max(0, ...dates.map((date) => formatX(date).length * CHAR_WIDTH));
  $: xEvery = responsive && dates.length > 1 ? Math.max(1, Math.ceil((xLabelWidth + 6) / bandWidth)) : 1;
  /** Marcadores: x interpolado pela data; rótulo à esquerda da linha na metade direita; linhas que colidem vão para baixo. */
  $: markerLayout = (() => {
    const placed: Array<{ key: string; x: number; label: string; text: string; detail: string; anchor: 'start' | 'end'; row: number; from: number; to: number }> = [];
    markers.forEach((marker, index) => {
      const x = markerX(dates, xs, marker.date, markerOffsetDays);
      if (x === null) return;
      const anchor: 'start' | 'end' = x > (left + right) / 2 ? 'end' : 'start';
      // Rótulo longo demais para o lado escolhido é cortado com reticências;
      // o texto inteiro fica no title e na lista de eventos da página.
      const room = anchor === 'end' ? x - 8 : width - x - 8;
      const maxChars = Math.max(4, Math.floor(room / EVENT_CHAR));
      const text = marker.label.length > maxChars ? `${marker.label.slice(0, maxChars - 1).trimEnd()}…` : marker.label;
      const textWidth = text.length * EVENT_CHAR;
      const from = anchor === 'end' ? x - 4 - textWidth : x + 4;
      const to = from + textWidth;
      let row = 0;
      while (placed.some((other) => other.row === row && from < other.to + 8 && other.from < to + 8)) row += 1;
      placed.push({ key: `${marker.date}|${index}`, x, label: marker.label, text, detail: marker.detail ?? '', anchor, row, from, to });
    });
    return placed;
  })();
  $: markerRows = markerLayout.length ? Math.max(...markerLayout.map((marker) => marker.row)) + 1 : 0;
  // 2) Vertical: o topo desce para caber os rótulos dos eventos; a base desce para a legenda do eixo X.
  // Com variação, cada rótulo ganha uma linha a mais (acima do número de cima, abaixo do de baixo).
  $: deltaPad = showDeltas ? 15 : 0;
  $: top = 30 + markerRows * 15 + deltaPad;
  $: bottom = 236 + markerRows * 15 + deltaPad * 2;
  // Modo responsivo: base justa (datas + legenda do eixo); o fixo mantém os 300 de antes.
  $: height = responsive ? bottom + (xAxisLabel ? 46 : 30) : bottom + 64 + (xAxisLabel ? 16 : 0);
  $: PLOT = { left, right, top, bottom, width, height };
  // Linha de base dos rótulos de evento. Com variação, a faixa extra fica ENTRE os eventos e o
  // gráfico: a variação escrita acima do número mais alto não sobe até o rótulo do evento.
  $: markerBase = PLOT.top - 10 - deltaPad;

  $: yFor = (value: number): number => {
    const clamped = Math.min(yMax, Math.max(yMin, value));
    return PLOT.bottom - ((clamped - yMin) / (yMax - yMin)) * (PLOT.bottom - PLOT.top);
  };
  function fmt(value: number): string {
    if (formatValue) return formatValue(value);
    return decimals === 0 ? String(Math.round(value)) : formatNumber(value);
  }
  function tickText(tick: number): string {
    const text = Number.isInteger(tick) ? String(Math.abs(tick)) : formatNumber(Math.abs(tick));
    return `${tick < 0 ? '−' : ''}${text}${unit}`;
  }

  $: gridlines = yTicks.map((tick) => ({ tick, y: yFor(tick), text: tickText(tick) }));
  $: referenceY = referenceValue !== null && referenceValue >= yMin && referenceValue <= yMax ? yFor(referenceValue) : null;

  /** Uma coluna por data: posição, marcas de cada série e o texto acessível. */
  $: columns = dates.map((date, index) => {
    const marks = shown
      .map((item) => ({ item, point: item.points.find((candidate) => candidate.date === date) }))
      .filter((entry): entry is { item: (typeof shown)[number]; point: LabelledPoint } => Boolean(entry.point))
      .map((entry) => ({ key: entry.item.key, label: entry.item.label, color: entry.item.color, point: entry.point, cy: yFor(entry.point.value) }));
    return {
      date,
      index,
      x: xs[index],
      marks,
      aria: `${longX(date)}: ${marks
        .map((mark) => {
          const words = showDeltas ? deltaWords(deltaByKey.get(mark.key)?.get(date)) : '';
          return `${mark.label} ${fmt(mark.point.value)}${unit}${words ? ` (${words})` : ''}`;
        })
        .join(', ')}`,
      xLabel: formatX(date),
      // O último rótulo sempre aparece; o regular que ficaria colado nele sai.
      showXLabel: index === dates.length - 1 || (index % xEvery === 0 && dates.length - 1 - index >= xEvery),
    };
  });

  /** Variação de cada ponto frente ao ponto anterior da mesma série (por data). */
  $: deltaByKey = new Map(
    shown.map((item) => {
      const sorted = [...item.points].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
      const byDate = new Map<string, number>();
      sorted.forEach((point, index) => {
        if (index > 0) byDate.set(point.date, Math.round((point.value - sorted[index - 1].value) * 10) / 10);
      });
      return [item.key, byDate] as const;
    }),
  );
  function deltaText(delta: number): string {
    if (Math.abs(delta) < 0.05) return '=';
    return `${delta > 0 ? '▲' : '▼'}${fmt(Math.abs(delta))}`;
  }
  function deltaWords(delta: number | undefined): string {
    if (delta === undefined) return '';
    if (Math.abs(delta) < 0.05) return 'igual à rodada anterior';
    return `${delta > 0 ? 'subiu' : 'caiu'} ${fmt(Math.abs(delta))} frente à rodada anterior`;
  }

  $: lines = shown.map((item) => ({
    ...item,
    path: columns
      .map((column) => {
        const mark = column.marks.find((entry) => entry.key === item.key);
        return mark ? `${column.x},${mark.cy}` : null;
      })
      .filter((segment): segment is string => segment !== null)
      .join(' '),
  }));

  type LabelAnchor = 'middle' | 'start' | 'end';
  type LabelBox = { x0: number; x1: number; y0: number; y1: number };
  const VALUE_CHAR = 7.2;
  /** Caixa ocupada por um rótulo de valor (mesma geometria usada para cortar o tracejado dos eventos). */
  function valueBox(x: number, baseline: number, anchor: LabelAnchor, text: string): LabelBox {
    const textWidth = text.length * VALUE_CHAR;
    const from = anchor === 'middle' ? x - textWidth / 2 : anchor === 'end' ? x - textWidth : x;
    return { x0: from - 2, x1: from + textWidth + 2, y0: baseline - 12, y1: baseline + 4 };
  }
  const overlaps = (a: LabelBox, b: LabelBox): boolean => a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
  /** Degrau vertical das fileiras extras de rótulo (só no modo avoidLines). */
  const STAGGER = 15;

  /**
   * Um rótulo por ponto, sem colisão: por coluna, a série mais alta escreve
   * acima; a mais baixa, abaixo; a do meio vai para o lado que tiver espaço
   * e, se não houver, para a direita do ponto.
   */
  $: defaultLabels = columns.flatMap((column) => {
    const ordered = [...column.marks].sort((a, b) => b.point.value - a.point.value);
    return ordered.map((mark, rank) => {
      const y = mark.cy;
      let dx = 0;
      let dy = -12;
      let anchor: LabelAnchor = 'middle';
      if (rank === ordered.length - 1 && ordered.length > 1) {
        dy = 20;
      } else if (rank > 0) {
        const above = ordered[rank - 1].cy;
        const below = ordered[rank + 1].cy;
        if (y - above >= LABEL_GAP) dy = -12;
        else if (below - y >= LABEL_GAP) dy = 20;
        else {
          dx = 10;
          dy = 4;
          anchor = 'start';
        }
      }
      return { x: column.x, y, dx, dy, anchor: anchor as LabelAnchor, text: fmt(mark.point.value), key: mark.key, date: column.date, rank, count: ordered.length };
    });
  });

  /**
   * avoidLines: numa coluna com UM ponto só, o rótulo escolhe entre acima,
   * abaixo, as quatro diagonais e duas fileiras extras (ex.: "+5,6" no meio
   * da descida da linha de 2026 no gráfico "mesma distância"). Vence o lugar
   * que não cruza linha, não cobre ponto, rótulo de outro ponto nem rótulo de
   * evento e não sai da área do gráfico; empate fica com o desenho padrão (o
   * primeiro da lista), então sem colisão nada muda (integração, 23/09/2026).
   */
  const ABOVE = [-12, -12 - STAGGER, -12 - 2 * STAGGER].map((dy) => ({ dx: 0, dy, anchor: 'middle' as LabelAnchor }));
  const BELOW = [20, 20 + STAGGER, 20 + 2 * STAGGER].map((dy) => ({ dx: 0, dy, anchor: 'middle' as LabelAnchor }));
  const DIAGONALS: Array<{ dx: number; dy: number; anchor: LabelAnchor }> = [
    { dx: 9, dy: -7, anchor: 'start' },
    { dx: -9, dy: -7, anchor: 'end' },
    { dx: 9, dy: 16, anchor: 'start' },
    { dx: -9, dy: 16, anchor: 'end' },
  ];
  type LabelOption = { dx: number; dy: number; anchor: LabelAnchor };
  function labelOptions(label: { dx: number; dy: number; anchor: LabelAnchor; rank: number; count: number }): LabelOption[] {
    const current: LabelOption = { dx: label.dx, dy: label.dy, anchor: label.anchor };
    let options: LabelOption[] = [];
    if (label.count === 1 && avoidLines) options = [ABOVE[0], BELOW[0], ...DIAGONALS, ABOVE[1], BELOW[1], ABOVE[2], BELOW[2]];
    const rest = options.filter((option) => option.dx !== current.dx || option.dy !== current.dy || option.anchor !== current.anchor);
    return [current, ...rest];
  }
  $: labels = (() => {
    if (!avoidLines) return defaultLabels;
    const circles = columns.flatMap((column) => column.marks.map((mark) => ({ x: column.x, y: mark.cy, key: `${mark.key}|${column.date}` })));
    const eventBoxes: LabelBox[] = markerLayout.map((marker) => {
      const baseline = markerBase - marker.row * 15;
      return { x0: marker.from - 2, x1: marker.to + 2, y0: baseline - 11, y1: baseline + 3 };
    });
    const boxes = defaultLabels.map((label) => valueBox(label.x + label.dx, label.y + label.dy, label.anchor, label.text));
    const result = defaultLabels.map((label) => ({ ...label }));
    result.forEach((label, index) => {
      const options = labelOptions(label);
      if (options.length < 2) return;
      const own = `${label.key}|${label.date}`;
      const score = (option: LabelOption): number => {
        const box = valueBox(label.x + option.dx, label.y + option.dy, option.anchor, label.text);
        let total = lineCrossings(box);
        if (box.x0 < 0 || box.x1 > PLOT.width) total += 10;
        circles.forEach((circle) => {
          if (circle.key === own) return;
          if (circle.x + 6 > box.x0 && circle.x - 6 < box.x1 && circle.y + 6 > box.y0 && circle.y - 6 < box.y1) total += 5;
        });
        boxes.forEach((other, otherIndex) => {
          if (otherIndex !== index && overlaps(box, other)) total += 5;
        });
        eventBoxes.forEach((other) => {
          if (overlaps(box, other)) total += 5;
        });
        return total;
      };
      let best = options[0];
      let bestScore = score(best);
      options.slice(1).forEach((option) => {
        const value = score(option);
        if (value < bestScore) {
          best = option;
          bestScore = value;
        }
      });
      label.dx = best.dx;
      label.dy = best.dy;
      label.anchor = best.anchor;
      boxes[index] = valueBox(label.x + best.dx, label.y + best.dy, best.anchor, label.text);
    });
    return result;
  })();

  /**
   * Variação junto do número: por fora do rótulo (acima do de cima, abaixo do
   * de baixo), para nunca ficar entre o número e o ponto. Se ali encostar num
   * rótulo de evento, noutro número ou noutra variação, vai para o lado do
   * número (direita, depois esquerda); rótulo lateral leva a variação abaixo.
   */
  const DELTA_CHAR = 6.2;
  function deltaBox(x: number, y: number, anchor: LabelAnchor, text: string): LabelBox {
    const textWidth = text.length * DELTA_CHAR;
    const from = anchor === 'middle' ? x - textWidth / 2 : anchor === 'end' ? x - textWidth : x;
    return { x0: from - 2, x1: from + textWidth + 2, y0: y - 10, y1: y + 3 };
  }
  $: deltaLabels = (() => {
    if (!showDeltas) return [];
    // Margem extra: a largura do rótulo de evento é estimada (6,5 px por caractere) e o real sai maior.
    const eventBoxes: LabelBox[] = markerLayout.map((marker) => {
      const baseline = markerBase - marker.row * 15;
      return { x0: marker.from - 10, x1: marker.to + 10, y0: baseline - 12, y1: baseline + 3 };
    });
    const valueBoxes = labels.map((label) => valueBox(label.x + label.dx, label.y + label.dy, label.anchor, label.text));
    const placed: LabelBox[] = [];
    return labels.flatMap((label, index) => {
      const delta = deltaByKey.get(label.key)?.get(label.date);
      if (delta === undefined) return [];
      const text = deltaText(delta);
      const own = valueBoxes[index];
      const baseline = label.y + label.dy;
      const side = label.anchor !== 'middle';
      // Folga medida no Chromium: 14 abaixo e 15 acima não encostam na caixa do número (12 px, negrito).
      const outward = { x: label.x + label.dx, y: side || label.dy > 0 ? baseline + 14 : baseline - 15, anchor: label.anchor };
      const options = [
        outward,
        { x: own.x1 + 3, y: baseline, anchor: 'start' as LabelAnchor },
        { x: own.x0 - 3, y: baseline, anchor: 'end' as LabelAnchor },
      ];
      // Nenhum lugar livre: fica o que colide menos, e cobrir o rótulo de um evento pesa mais.
      const score = (box: LabelBox) =>
        10 * eventBoxes.filter((other) => overlaps(box, other)).length +
        4 * valueBoxes.filter((other, otherIndex) => otherIndex !== index && overlaps(box, other)).length +
        4 * placed.filter((other) => overlaps(box, other)).length +
        (box.x0 < 0 || box.x1 > PLOT.width ? 6 : 0);
      let chosen = options[0];
      let best = score(deltaBox(chosen.x, chosen.y, chosen.anchor, text));
      options.slice(1).forEach((option) => {
        const value = score(deltaBox(option.x, option.y, option.anchor, text));
        if (value < best) {
          chosen = option;
          best = value;
        }
      });
      const box = deltaBox(chosen.x, chosen.y, chosen.anchor, text);
      placed.push(box);
      return [{
        key: `${label.key}|${label.date}`,
        x: chosen.x,
        y: chosen.y,
        anchor: chosen.anchor,
        text,
        color: shown.find((item) => item.key === label.key)?.color ?? PALETTE[0],
        direction: Math.abs(delta) < 0.05 ? 'flat' : delta > 0 ? 'up' : 'down',
        box,
      }];
    });
  })();

  /** Segmentos de todas as linhas desenhadas (em ordem de x), para o rótulo desviar delas. */
  $: segments = shown.flatMap((item) => {
    const points = columns
      .map((column) => {
        const mark = column.marks.find((entry) => entry.key === item.key);
        return mark ? { x: column.x, y: mark.cy } : null;
      })
      .filter((point): point is { x: number; y: number } => point !== null);
    return points.slice(1).map((point, index) => ({ ax: points[index].x, ay: points[index].y, bx: point.x, by: point.y }));
  }).concat(
    // A linha de referência (ex.: o zero do "mesma distância") também é linha: o rótulo não senta nela.
    referenceY !== null ? [{ ax: PLOT.left - 6, ay: referenceY, bx: PLOT.right, by: referenceY }] : [],
  );
  /** Quantos segmentos cruzam a caixa de um rótulo; caixa fora da área útil também conta como colisão. */
  $: lineCrossings = (box: LabelBox): number => {
    let count = 0;
    segments.forEach((segment) => {
      const from = Math.max(segment.ax, box.x0);
      const to = Math.min(segment.bx, box.x1);
      if (from > to || segment.bx === segment.ax) return;
      const at = (value: number) => segment.ay + ((value - segment.ax) / (segment.bx - segment.ax)) * (segment.by - segment.ay);
      const ya = at(from);
      const yb = at(to);
      if (Math.max(ya, yb) >= box.y0 && Math.min(ya, yb) <= box.y1) count += 1;
    });
    // Rótulo para fora da área do gráfico também conta como colisão (datas do eixo, borda de cima).
    if (box.y1 > PLOT.bottom - 2 || box.y0 < PLOT.top - 24) count += 10;
    return count;
  };

  /**
   * A linha tracejada de um evento é interrompida onde passaria por cima de
   * um número: o valor escrito vale mais que o tracejado.
   */
  $: markerSegments = markerLayout.map((marker) => {
    const cuts = labels
      .map((label) => {
        const box = valueBox(label.x + label.dx, label.y + label.dy, label.anchor, label.text);
        return { from: box.x0, to: box.x1, top: box.y0, bottom: box.y1 };
      })
      // A variação escrita junto do número também corta o tracejado.
      .concat(deltaLabels.map((delta) => ({ from: delta.box.x0, to: delta.box.x1, top: delta.box.y0, bottom: delta.box.y1 })))
      // Rótulo de OUTRO evento numa fileira de baixo também corta o tracejado.
      .concat(
        markerLayout
          .filter((other) => other.key !== marker.key)
          .map((other) => {
            const baseline = markerBase - other.row * 15;
            return { from: other.from - 2, to: other.to + 2, top: baseline - 11, bottom: baseline + 3 };
          }),
      )
      .filter((box) => marker.x >= box.from && marker.x <= box.to)
      .sort((a, b) => a.top - b.top);
    const segments: Array<{ y1: number; y2: number }> = [];
    let start = markerBase + 4 - marker.row * 15;
    cuts.forEach((box) => {
      if (box.top > start) segments.push({ y1: start, y2: Math.min(box.top, PLOT.bottom) });
      start = Math.max(start, box.bottom);
    });
    if (start < PLOT.bottom) segments.push({ y1: start, y2: PLOT.bottom });
    return { key: marker.key, x: marker.x, segments };
  });

  $: hovered = hoveredIndex === null ? null : (columns[hoveredIndex] ?? null);
  // Tooltip ao lado da coluna (à direita na metade esquerda, à esquerda na outra), nunca em cima do ponto.
  $: tooltipStyle = hovered
    ? hovered.x < PLOT.width / 2
      ? `left:${((hovered.x + 14) / PLOT.width) * 100}%`
      : `right:${((PLOT.width - hovered.x + 14) / PLOT.width) * 100}%`
    : '';
</script>

<figure class="labelled-line" aria-label={ariaLabel}>
  {#if title}
    <figcaption>
      <strong>{title}</strong>
      {#if description}<span>{description}</span>{/if}
    </figcaption>
  {/if}

  {#if shown.length && showLegend}
    <div class="labelled-legend" role="list" aria-label="Séries do gráfico">
      {#each shown as item}
        <span role="listitem" style={`--series-color:${item.color}`}><i aria-hidden="true" class:dashed={item.dashed}></i>{item.label}</span>
      {/each}
      {#if showDeltas}<span class="labelled-delta-note" role="listitem"><b aria-hidden="true">▲▼</b> {deltaNote}</span>{/if}
    </div>
  {:else if showDeltas}
    <p class="labelled-delta-note labelled-delta-solo"><b aria-hidden="true">▲▼</b> {deltaNote}</p>
  {/if}

  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <div class="labelled-wrap" class:labelled-responsive={responsive} class:labelled-scrollable={scrollable} tabindex="0" role="region" aria-label={ariaLabel} onmouseleave={() => (hoveredIndex = null)} bind:clientWidth={measuredWidth}>
    {#if dates.length}
      <!-- O quadro tem a largura do gráfico: quando passa da tela, o wrap rola e o tooltip acompanha. -->
      <div class="labelled-canvas" style={scrollable ? `width:${PLOT.width}px` : undefined}>
      <svg viewBox={`0 0 ${PLOT.width} ${PLOT.height}`} role="img" aria-label={`${title || ariaLabel}. Valores na tabela abaixo.`}>
        {#each gridlines as grid}
          <line class="chart-gridline" x1={PLOT.left - 6} x2={PLOT.right} y1={grid.y} y2={grid.y} />
          <text class="chart-axis-label" x={PLOT.left - 10} y={grid.y + 4} text-anchor="end">{grid.text}</text>
        {/each}
        <line class="chart-axis" x1={PLOT.left - 6} x2={PLOT.right} y1={PLOT.bottom} y2={PLOT.bottom} />
        {#if referenceY !== null}
          <line class="labelled-reference" x1={PLOT.left - 6} x2={PLOT.right} y1={referenceY} y2={referenceY} />
        {/if}
        {#if xAxisLabel}
          <text class="chart-axis-label labelled-x-title" x={(PLOT.left + PLOT.right) / 2} y={PLOT.bottom + 38} text-anchor="middle">{xAxisLabel}</text>
        {/if}

        {#each markerSegments as marker (marker.key)}
          {#each marker.segments as segment}
            <line class="labelled-marker-line" x1={marker.x} x2={marker.x} y1={segment.y1} y2={segment.y2} />
          {/each}
        {/each}

        {#each columns as column (column.date)}
          {#if column.showXLabel}
            <text class="chart-axis-label labelled-x" x={column.x} y={PLOT.bottom + 18} text-anchor="middle">{column.xLabel}</text>
          {/if}
          {#if hoveredIndex === column.index}
            <line class="labelled-crosshair" x1={column.x} x2={column.x} y1={PLOT.top - 8} y2={PLOT.bottom} />
          {/if}
        {/each}

        {#each lines as line (line.key)}
          {#if line.path.includes(' ')}
            <polyline class="labelled-path" points={line.path} stroke={line.color} fill="none" stroke-dasharray={line.dashed ? '7 5' : undefined} />
          {/if}
        {/each}

        {#each columns as column (column.date)}
          {#each column.marks as mark (mark.key)}
            <circle class="labelled-mark" cx={column.x} cy={mark.cy} r="5.5" fill={mark.color} />
          {/each}
        {/each}

        {#each labels as label (`${label.key}|${label.date}`)}
          <text
            class="labelled-value"
            x={label.x + label.dx}
            y={label.y + label.dy}
            text-anchor={label.anchor}
            data-series={label.key}
            data-date={label.date}
          >{label.text}</text>
        {/each}

        {#each deltaLabels as delta (delta.key)}
          <text
            class="labelled-delta"
            x={delta.x}
            y={delta.y}
            text-anchor={delta.anchor}
            fill={delta.color}
            data-direction={delta.direction}
            data-delta-for={delta.key}
          >{delta.text}</text>
        {/each}

        <!-- Alvos de hover maiores que a marca: uma faixa por coluna. -->
        {#each columns as column (column.date)}
          <rect
            class="labelled-hit"
            x={column.x - bandWidth / 2}
            y={PLOT.top - 10}
            width={bandWidth}
            height={PLOT.bottom - PLOT.top + 10}
            fill="transparent"
            tabindex="0"
            role="graphics-symbol"
            aria-label={column.aria}
            onmouseenter={() => (hoveredIndex = column.index)}
            onfocus={() => (hoveredIndex = column.index)}
            onblur={() => (hoveredIndex = null)}
          />
        {/each}

        <!-- Rótulo curto de cada evento, por cima dos alvos de hover; o detalhe fica no title (e na nota da página). -->
        {#each markerLayout as marker (marker.key)}
          <text
            class="labelled-marker-label"
            x={marker.anchor === 'end' ? marker.x - 4 : marker.x + 4}
            y={markerBase - marker.row * 15}
            text-anchor={marker.anchor}
          ><title>{marker.detail ? `${marker.label}: ${marker.detail}` : marker.label}</title>{marker.text}</text>
        {/each}
      </svg>

      {#if hovered && hovered.marks.length}
        <div class="labelled-tooltip" role="status" style={tooltipStyle}>
          <strong>{longX(hovered.date)}</strong>
          {#each hovered.marks as mark}
            {@const delta = showDeltas ? deltaByKey.get(mark.key)?.get(hovered.date) : undefined}
            <span style={`--series-color:${mark.color}`}><i aria-hidden="true"></i>{mark.label}: <b>{fmt(mark.point.value)}{unit}</b>{#if delta !== undefined}<em class="labelled-tooltip-delta">{deltaText(delta)} · {deltaWords(delta)}</em>{/if}</span>
          {/each}
          {#if hovered.marks[0].point.note}<small>{hovered.marks[0].point.note}</small>{/if}
        </div>
      {/if}
      </div>
    {:else}
      <p class="small muted">Sem medições para desenhar.</p>
    {/if}
  </div>
  {#if scrollable}<p class="labelled-scroll-hint">Deslize o gráfico para o lado para ver todas as rodadas.</p>{/if}

  {#if dates.length && showTable}
    <details class="labelled-table">
      <summary>Ver os valores em tabela</summary>
      <DataTable label={tableLabel}>
        <table>
          <thead>
            <tr>
              <th scope="col">Medição</th>
              {#each shown as item}<th scope="col" class="num">{item.label}</th>{/each}
              <th scope="col">Observação</th>
            </tr>
          </thead>
          <tbody>
            {#each columns as column (column.date)}
              <tr>
                <th scope="row">{longX(column.date)}</th>
                {#each shown as item}
                  {@const mark = column.marks.find((entry) => entry.key === item.key)}
                  <td class="num">{mark ? `${fmt(mark.point.value)}${unit}` : '—'}</td>
                {/each}
                <td>{column.marks[0]?.point.note ?? ''}{#if column.marks[0]?.point.url} <a href={column.marks[0].point.url} target="_blank" rel="noreferrer">fonte ↗</a>{/if}</td>
              </tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
    </details>
  {/if}
</figure>

<style>
  .labelled-line { margin: 0; min-width: 0; }
  .labelled-line figcaption { display: flex; flex-direction: column; gap: 0.15rem; margin-bottom: 0.5rem; }
  .labelled-line figcaption strong { font-size: 1rem; }
  .labelled-line figcaption span { color: var(--muted); font-size: 0.85rem; }
  .labelled-legend { display: flex; flex-wrap: wrap; gap: 0.35rem 1rem; margin-bottom: 0.35rem; font-size: 0.85rem; }
  .labelled-legend span, .labelled-tooltip span { display: inline-flex; align-items: center; gap: 0.4rem; }
  .labelled-legend i, .labelled-tooltip i { width: 14px; height: 3px; border-radius: 2px; background: var(--series-color); display: inline-block; }
  .labelled-legend i.dashed { background: repeating-linear-gradient(90deg, var(--series-color) 0 5px, transparent 5px 8px); }
  .labelled-delta-note { color: var(--muted); font-size: 0.78rem; }
  .labelled-delta-note b { font-size: 0.65rem; letter-spacing: -0.05em; margin-right: 0.15rem; }
  .labelled-delta-solo { margin: 0 0 0.35rem; }
  .labelled-wrap { position: relative; }
  /* Responsivo: a largura do quadro vem só do contêiner, nunca do gráfico
     (sem isso, o gráfico largo alarga a grade, que alarga o quadro, que
     desliga a rolagem — e o desenho fica oscilando). */
  .labelled-responsive { contain: inline-size; max-width: 100%; }
  .labelled-scrollable { overflow-x: auto; overscroll-behavior-x: contain; -webkit-overflow-scrolling: touch; }
  .labelled-canvas { position: relative; }
  .labelled-scroll-hint { margin: 0.25rem 0 0; color: var(--muted); font-size: 0.75rem; }
  .labelled-wrap svg { width: 100%; height: auto; display: block; }
  .labelled-path { stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
  .labelled-mark { stroke: #fff; stroke-width: 2; }
  .labelled-value {
    font-size: 12px;
    font-weight: 700;
    fill: var(--text, #0b0b0b);
    paint-order: stroke;
    stroke: #fff;
    stroke-width: 3px;
    stroke-linejoin: round;
    font-variant-numeric: tabular-nums;
    pointer-events: none;
  }
  .labelled-delta {
    font-size: 10px;
    font-weight: 600;
    paint-order: stroke;
    stroke: #fff;
    stroke-width: 3px;
    stroke-linejoin: round;
    font-variant-numeric: tabular-nums;
    pointer-events: none;
  }
  .labelled-delta[data-direction='flat'] { fill: var(--muted, #6b7280); }
  .labelled-tooltip-delta { margin-left: 0.35rem; color: var(--muted); font-style: normal; font-size: 0.75rem; }
  .labelled-x { font-size: 10.5px; }
  .labelled-x-title { font-size: 10.5px; font-style: italic; }
  .labelled-reference { stroke: var(--secondary, #526171); stroke-width: 1.25; }
  .labelled-marker-line { stroke: var(--secondary, #526171); stroke-width: 1.5; stroke-dasharray: 4 3; }
  .labelled-marker-label {
    font-size: 10.5px;
    font-weight: 700;
    fill: var(--secondary, #526171);
    paint-order: stroke;
    stroke: #fff;
    stroke-width: 3px;
    stroke-linejoin: round;
    cursor: help;
  }
  .labelled-crosshair { stroke: var(--border, #d8d6cf); stroke-width: 1; stroke-dasharray: 3 3; }
  .labelled-hit:focus { outline: none; }
  .labelled-hit:focus-visible { stroke: var(--accent, #1f65d6); stroke-width: 1; }
  .labelled-tooltip {
    position: absolute;
    top: 0;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    padding: 0.45rem 0.6rem;
    background: #fff;
    border: 1px solid var(--border, #d8d6cf);
    border-radius: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    font-size: 0.8rem;
    pointer-events: none;
    max-width: 240px;
  }
  .labelled-tooltip small { color: var(--muted); }
  .labelled-table { margin-top: 0.5rem; font-size: 0.85rem; }
  .labelled-table summary { cursor: pointer; color: var(--muted); }
</style>
