// Monitor de cobertura TSE × produto (operations.json → coverage_monitor).
// Contrato gerado por src/agregador/discovery/coverage.py e validado por
// schemas/site/operations.schema.json. Fica separado de types.ts de propósito:
// o campo é opcional e o painel operacional é o único consumidor.
import type { OperationsPayload } from './types';

export type CoverageStatus =
  | 'completo'
  | 'parcial_t1'
  | 'parcial_t2'
  | 'imprensa_conferida_somente_comparativo'
  | 'validated_aguardando'
  | 'bloqueado'
  | 'descoberto_sem_cenario'
  | 'nao_descoberto'
  | 'ainda_nao_divulgado';

export type PressTurnStatus = 'verified' | 'conflict' | 'insufficient' | null;

export interface CoverageSource {
  source_id: string | null;
  url: string | null;
  state: string | null;
  transitioned_at: string | null;
  item_id?: string | null;
}

export interface CoverageRow {
  registration_no: string;
  planned_publish_date: string;
  field_start: string | null;
  field_end: string | null;
  sample_size: number | null;
  national_basis: string;
  status: CoverageStatus;
  status_label?: string;
  funnel_status?: CoverageStatus;
  accepted_turns: Array<1 | 2>;
  blockers: string[];
  last_source: CoverageSource | null;
  days_late: number;
  alert: boolean;
  press_verified: Record<'1' | '2', PressTurnStatus> | null;
}

export interface CoverageHouse {
  house_id: string;
  name: string;
  cnpjs?: string[];
  press_verified_layer?: boolean;
  expected: number;
  complete: number;
  partial: number;
  missing: number;
  upcoming?: number;
  status_counts?: Partial<Record<CoverageStatus, number>>;
  rows: CoverageRow[];
}

export interface CoverageAlert {
  house_id: string;
  house_name?: string;
  registration_no: string;
  planned_publish_date: string;
  days_late?: number;
  message: string;
}

export interface CycleStepStatus {
  at: string;
  ok: boolean;
  error?: string;
  fetched?: number;
  fetch_failures?: number;
  alerts?: number;
}

// --- Aviso "Pesquisas de hoje" (coverage_monitor.today, desde a 1.1.0) -------

export type TodayStatus = 'no_radar' | 'em_leitura' | 'aguardando_divulgacao' | 'somente_comparativo';
export type TodayTone = 'green' | 'amber' | 'gray';

export interface TodayPollRow {
  registration_no: string;
  house_id?: string | null;
  house_name: string;
  institute_name?: string | null;
  /** Casa do produto (as casas do agregado); `false` = "fora do agregado", sempre em cinza. */
  in_aggregate: boolean;
  planned_publish_date: string;
  field_start?: string | null;
  field_end?: string | null;
  sample_size?: number | null;
  own_poll?: boolean | null;
  status: TodayStatus;
  status_label: string;
  tone: TodayTone;
  accepted_turns: Array<1 | 2>;
  /** Motivo principal em linguagem simples (bloqueio do funil ou próximo passo). */
  reason?: string | null;
  blocker?: string | null;
  coverage_status?: string;
  inclusion: 'prevista_hoje' | 'divulgada_ultimas_24h';
  first_seen_at?: string | null;
  national_basis?: string;
  last_source?: CoverageSource | null;
}

export interface TodayPollsBlock {
  date: string;
  generated_at: string;
  recent_hours?: number;
  rule?: string;
  status_labels?: Partial<Record<TodayStatus, string>>;
  counts: Partial<Record<TodayStatus | 'fora_do_agregado', number>>;
  headline: string;
  rows: TodayPollRow[];
}

export interface CoverageMonitor {
  version: string;
  generated_at: string;
  as_of_date: string;
  window_start: string;
  future_days?: number;
  alert_after_hours?: number;
  national_rule?: string;
  status_labels?: Partial<Record<CoverageStatus, string>>;
  totals: Partial<Record<CoverageStatus, number>>;
  expected_due?: number;
  alerts: CoverageAlert[];
  houses: CoverageHouse[];
  excluded_national_false_positives?: Array<{ registration_no: string; house_id: string; reason: string }>;
  cycle_steps?: { cycle_press?: CycleStepStatus; coverage_monitor?: CycleStepStatus };
  /** Aviso "Pesquisas de hoje"; ausente em snapshots anteriores à 1.1.0. */
  today?: TodayPollsBlock | null;
  notes?: string[];
}

/** Mantido por compatibilidade: `coverage_monitor` agora é campo opcional do próprio OperationsPayload. */
export type OperationsWithCoverage = OperationsPayload;

export const COVERAGE_STATUS_LABELS: Record<CoverageStatus, string> = {
  completo: '1º e 2º turno aceitos',
  parcial_t1: 'Só 1º turno aceito',
  parcial_t2: 'Só 2º turno aceito',
  imprensa_conferida_somente_comparativo: 'Imprensa conferida · só comparativo',
  validated_aguardando: 'Validada · aguarda aceite',
  bloqueado: 'Bloqueada por gate',
  descoberto_sem_cenario: 'Material sem cenário',
  nao_descoberto: 'Não descoberta',
  ainda_nao_divulgado: 'Ainda não divulgada'
};

export type CoverageTone = 'complete' | 'partial' | 'press' | 'pending' | 'missing' | 'upcoming';

export const coverageTone = (status: CoverageStatus): CoverageTone => {
  if (status === 'completo') return 'complete';
  if (status === 'parcial_t1' || status === 'parcial_t2') return 'partial';
  if (status === 'imprensa_conferida_somente_comparativo') return 'press';
  if (status === 'ainda_nao_divulgado') return 'upcoming';
  if (status === 'nao_descoberto') return 'missing';
  return 'pending';
};

export const coverageStatusLabel = (row: Pick<CoverageRow, 'status' | 'status_label'>): string =>
  COVERAGE_STATUS_LABELS[row.status] ?? row.status_label ?? row.status;

export const pressTurnLabel = (value: PressTurnStatus): string =>
  value === 'verified' ? 'conferido' : value === 'conflict' ? 'divergente' : value === 'insufficient' ? 'insuficiente' : 'sem arquivo';

export const coverageMonitorOf = (operations: OperationsPayload): CoverageMonitor | null =>
  operations.coverage_monitor ?? null;

/** Âncora da seção de cobertura no painel de operação (OperationsPanel, rota /laboratorio). */
export const COVERAGE_SECTION_ID = 'cobertura-tse';
export const COVERAGE_SECTION_HREF = `/laboratorio#${COVERAGE_SECTION_ID}`;

export const todayPollsOf = (operations: OperationsPayload | null | undefined): TodayPollsBlock | null =>
  operations?.coverage_monitor?.today ?? null;

/** Texto curto do selo (verde/âmbar/cinza). Casa fora do agregado: sempre "fora do agregado". */
export const todayBadgeLabel = (row: Pick<TodayPollRow, 'status' | 'in_aggregate'>): string => {
  if (!row.in_aggregate) return 'fora do agregado';
  if (row.status === 'no_radar') return 'no Radar';
  if (row.status === 'em_leitura') return 'em leitura';
  if (row.status === 'somente_comparativo') return 'comparativo';
  return 'aguardando';
};

/** Casa fora do agregado é sempre cinza, qualquer que seja o status. */
export const todayTone = (row: Pick<TodayPollRow, 'tone' | 'in_aggregate'>): TodayTone => (row.in_aggregate ? row.tone : 'gray');

const shortDay = (value?: string | null): string | null => {
  const found = /^(\d{4})-(\d{2})-(\d{2})/.exec(value ?? '');
  return found ? `${found[3]}/${found[2]}` : null;
};

const integer = new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 });

/** "BR-01739/2026 · campo 20/09–23/09 · n=3.000" */
export const todayRowMeta = (row: Pick<TodayPollRow, 'registration_no' | 'field_start' | 'field_end' | 'sample_size'>): string => {
  const parts = [row.registration_no];
  const start = shortDay(row.field_start);
  const end = shortDay(row.field_end);
  if (start && end) parts.push(start === end ? `campo ${start}` : `campo ${start}–${end}`);
  else if (start || end) parts.push(`campo ${start ?? end}`);
  if (typeof row.sample_size === 'number') parts.push(`n=${integer.format(row.sample_size)}`);
  return parts.join(' · ');
};

/** "divulgada, em leitura: o cenário completo ainda não foi separado no material" */
export const todayRowStatusText = (row: Pick<TodayPollRow, 'status_label' | 'reason'>): string =>
  row.reason ? `${row.status_label}: ${row.reason}` : row.status_label;

/** Data local de Brasília (AAAA-MM-DD), qualquer que seja o fuso do navegador. */
export const brasiliaDate = (now: Date = new Date()): string =>
  new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);

/** "Pesquisas de hoje" quando o bloco é do dia; "Pesquisas de 23/09" quando o watcher ainda não recalculou. */
export const todayPollsTitle = (block: Pick<TodayPollsBlock, 'date'>, now: Date = new Date()): string =>
  block.date === brasiliaDate(now) ? 'Pesquisas de hoje' : `Pesquisas de ${shortDay(block.date) ?? block.date}`;
